const records = $json.data.items || [];

return records.map(record => ({
  json: record
}));

// 这个节点兼容两种输入：
// 1. PDF Parser 服务返回：{ success, fields, text, engine, debug }
// 2. AI Agent 返回：text / response / output 里是一段 JSON 字符串

let data = {};
let source = 'unknown';

// ---------- 工具函数 ----------
function cleanString(v) {
  if (v === null || v === undefined) return '';
  return String(v).trim();
}

function cleanAmount(v) {
  if (v === null || v === undefined || v === '') return '';

  const s = String(v)
    .replace(/[,，¥￥元\s]/g, '')
    .trim();

  const m = s.match(/\d+(\.\d+)?/);
  return m ? Number(m[0]).toFixed(2) : '';
}

function cleanDate(v) {
  if (!v) return '';

  const s = String(v).trim();

  // YYYY-MM-DD / YYYY/M/D / YYYY.M.D
  let m = s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/);
  if (m) {
    return `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
  }

  // 2026年05月13日
  m = s.match(/(\d{4})年\s*(\d{1,2})月\s*(\d{1,2})日/);
  if (m) {
    return `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
  }

  // Date 可解析格式兜底
  const d = new Date(s);
  if (!isNaN(d)) {
    const y = d.getFullYear();
    const mo = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${mo}-${day}`;
  }

  return '';
}

// ---------- 情况 1：PDF Parser 服务返回 ----------
if ($json.fields && typeof $json.fields === 'object') {
  data = $json.fields;
  source = 'pdf_parser';
}

// ---------- 情况 2：AI Agent 返回 JSON 字符串 ----------
else {
  let raw = $json.text || $json.response || $json.output || '';

  raw = String(raw)
    .replace(/```json/g, '')
    .replace(/```/g, '')
    .trim();

  try {
    data = JSON.parse(raw);
    source = 'ai_agent';
  } catch (e) {
    return [
      {
        json: {
          解析失败: true,
          字段完整: false,
          失败原因: '无法解析 JSON：既没有 PDF Parser fields，也没有合法 AI JSON',
          原始内容: raw,
          source,
          record_id: $('循环处理附件').item.json.record_id,
          attachment_index: $('循环处理附件').item.json.attachment_index,
          attachment_name: $('循环处理附件').item.json.attachment_name,
        },
      },
    ];
  }
}

// ---------- 标准化字段 ----------
const normalized = {
  发票号码: cleanString(data['发票号码']),
  开票日期: cleanDate(data['开票日期']),
  购方名称: cleanString(data['购方名称']),
  销方名称: cleanString(data['销方名称']),
  价税合计: cleanAmount(data['价税合计']),

  source,
  解析失败: false,

  // PDF Parser 附加信息
  pdf_parser_success: $json.success === true,
  pdf_parser_engine: $json.engine || '',
  pdf_parser_text_length: $json.text_length || 0,
  pdf_parser_page_count: $json.page_count || 0,
  pdf_parser_text: $json.text || '',
  pdf_parser_debug: $json.debug || {},

  // 候选信息，方便排错
  公司名称候选: data['公司名称候选'] || [],
  纳税人识别号候选: data['纳税人识别号候选'] || [],
};

// ---------- 字段完整性判断 ----------
normalized.字段完整 = Boolean(
  normalized.发票号码 &&
  normalized.开票日期 &&
  normalized.购方名称 &&
  normalized.销方名称 &&
  normalized.价税合计
);

normalized.失败原因 = normalized.字段完整
  ? ''
  : [
      !normalized.发票号码 ? '缺少发票号码' : '',
      !normalized.开票日期 ? '缺少开票日期' : '',
      !normalized.购方名称 ? '缺少购方名称' : '',
      !normalized.销方名称 ? '缺少销方名称' : '',
      !normalized.价税合计 ? '缺少价税合计' : '',
    ].filter(Boolean).join('；');

const attachCtx = $('循环处理附件').item.json;
const withContext = {
  ...normalized,
  record_id: attachCtx.record_id,
  attachment_index: attachCtx.attachment_index,
  attachment_name: attachCtx.attachment_name,
};

return [{ json: withContext }];

function cleanString(v) {
  if (v === null || v === undefined) return '';
  return String(v).trim();
}

function cleanAmount(v) {
  if (v === null || v === undefined || v === '') return null;

  const s = String(v)
    .replace(/[,，¥￥元\s]/g, '')
    .trim();

  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

function dateToFeishuTimestamp(dateStr) {
  if (!dateStr) return null;

  const s = String(dateStr).trim();
  const m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (!m) return null;

  const y = Number(m[1]);
  const mo = Number(m[2]);
  const d = Number(m[3]);
  const dt = new Date(y, mo - 1, d, 0, 0, 0, 0);
  return dt.getTime();
}

if ($json.mergeStatus === 'merge_error') {
  return [
    {
      json: {
        feishu_ready: true,
        feishu_update_body: {
          fields: {
            识别状态: '错误合并',
            购方名称: $json.购方名称,
          },
        },
      },
    },
  ];
}

const invoiceNo = cleanString($json['发票号码']);
const invoiceDate = cleanString($json['开票日期']);
const buyerName = cleanString($json['购方名称']);
const sellerName = cleanString($json['销方名称']);
const totalAmount = cleanAmount($json['价税合计']);

const dateTimestamp = dateToFeishuTimestamp(invoiceDate);

const missing = [
  !invoiceNo ? '缺少发票号码' : '',
  !invoiceDate ? '缺少开票日期' : '',
  !dateTimestamp ? '开票日期格式无效' : '',
  !buyerName ? '缺少购方名称' : '',
  !sellerName ? '缺少销方名称' : '',
  totalAmount === null ? '价税合计格式无效' : '',
].filter(Boolean);

if (missing.length > 0) {
  return [
    {
      json: {
        ...$json,
        mergeStatus: 'error',
        feishu_ready: false,
        失败原因: missing.join('；'),
      },
    },
  ];
}

const fields = {
  发票号码: invoiceNo,
  开票日期: dateTimestamp,
  购方名称: buyerName,
  销方名称: sellerName,
  价税合计: totalAmount,
  识别状态: '已识别',
};

return [
  {
    json: {
      ...$json,
      feishu_ready: true,
      feishu_fields: fields,
      feishu_update_body: {
        fields,
      },
    },
  },
];

function unwrapAttachmentField(field) {
  if (Array.isArray(field)) return field;
  if (field && Array.isArray(field.value)) return field.value;
  return [];
}

function detectPdfStatus(item) {
  if (!item || typeof item !== 'object') return 'unknown';

  const name = String(item.name || item.text || item.title || '').trim().toLowerCase();
  const type = String(item.type || item.mime_type || item.mimeType || '').trim().toLowerCase();

  if (name.endsWith('.pdf')) return 'pdf';
  if (type.includes('pdf') || type === 'application/pdf') return 'pdf';

  const nonPdfExt = ['.doc', '.docx', '.xls', '.xlsx', '.jpg', '.jpeg', '.png'];
  if (nonPdfExt.some((ext) => name.endsWith(ext))) return 'non_pdf';

  return 'unknown';
}

const record = $('循环处理发票').item.json;
const recordId = record.record_id || '';
const attachments = unwrapAttachmentField((record.fields || {})['发票']);
const pdfs = attachments.filter((item) => detectPdfStatus(item) === 'pdf');

if (!pdfs.length) {
  return [
    {
      json: {
        skip: true,
        record_id: recordId,
        reason: '无发票PDF附件',
      },
    },
  ];
}

return pdfs.map((item, index) => ({
  json: {
    skip: false,
    record_id: recordId,
    attachment_index: index,
    attachment_total: pdfs.length,
    attachment_name: String(item.name || item.text || item.title || '').trim(),
    tmp_url: item.tmp_url || '',
  },
}));

const recordId = $('循环处理发票').first().json.record_id;
const items = $('PDF解析结果标准化').all()
  .map((i) => i.json)
  .filter((i) => i.record_id === recordId)
  .sort((a, b) => (a.attachment_index || 0) - (b.attachment_index || 0));

if (!items.length) {
  return [
    {
      json: {
        mergeStatus: 'error',
        record_id: recordId,
        失败原因: '未获取到解析结果',
      },
    },
  ];
}

if (items.some((i) => !i.字段完整 || i.解析失败)) {
  const reasons = items
    .filter((i) => !i.字段完整)
    .map((i) => {
      const name = i.attachment_name ? `[${i.attachment_name}]` : '';
      return `${name}${i.失败原因 || '识别字段不完整'}`.trim();
    })
    .filter(Boolean);

  return [
    {
      json: {
        mergeStatus: 'error',
        record_id: recordId,
        失败原因: reasons.join('；') || '部分发票识别字段不完整',
      },
    },
  ];
}

if (items.length === 1) {
  const one = { ...items[0] };
  delete one.attachment_index;
  delete one.attachment_name;
  delete one.attachment_total;
  return [{ json: { mergeStatus: 'ok', ...one } }];
}

const buyer = items[0].购方名称;
const seller = items[0].销方名称;
const partiesMatch = items.every((i) => i.购方名称 === buyer && i.销方名称 === seller);

if (!partiesMatch) {
  return [
    {
      json: {
        mergeStatus: 'merge_error',
        record_id: recordId,
        购方名称: '🔔发票附件中，有多张发票合并识别的，发票必须销售方和购买方一致。',
      },
    },
  ];
}

const total = items.reduce((sum, i) => sum + Number(i.价税合计 || 0), 0);
const dates = items.map((i) => i.开票日期).filter(Boolean).sort();

return [
  {
    json: {
      mergeStatus: 'ok',
      record_id: recordId,
      发票号码: items.map((i) => i.发票号码).join('，'),
      开票日期: dates[0] || '',
      购方名称: buyer,
      销方名称: seller,
      价税合计: total.toFixed(2),
      合并张数: items.length,
    },
  },
];
